import logging

import triton
import triton.language as tl

from flag_gems.utils import pointwise_dynamic

logger = logging.getLogger(__name__)


@pointwise_dynamic(is_tensor=[True, True], promotion_methods=[(0, 1, "INT_TO_FLOAT")])
@triton.jit
def heaviside_func(x, values):
    zeros = x - x
    ones = zeros + 1
    is_pos = x > zeros
    is_zero = x == zeros
    return tl.where(is_zero, values, tl.where(is_pos, ones, zeros))


def heaviside(input, values):
    logger.debug("GEMS HEAVISIDE")
    return heaviside_func(input, values)


def heaviside_out(input, values, out):
    logger.debug("GEMS HEAVISIDE_OUT")
    heaviside_func(input, values, out0=out)
    return out
